def freigaben_benennen(apps, schema_editor):
    """Schon freigegebene Vorlagen bekommen als Namen den Benutzer, der freigegeben hat."""
    Vorlage = apps.get_model("dokumente", "Vorlage")
    for vorlage in Vorlage.objects.filter(status="freigegeben", freigabe_durch=""):
        vorlage.freigabe_durch = f"Benutzer #{vorlage.freigegeben_von_id}"
        vorlage.save(update_fields=["freigabe_durch"])


